// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IRobinhoodToken is IERC20 {
    function totalEligibleBalance() external view returns (uint256);
    function bucketTotalBalance(uint8 bucket) external view returns (uint256);
    function getPastBalance(address account, uint256 blockNumber) external view returns (uint256);
    function getBucketCandidateLength(uint8 bucket) external view returns (uint256);
    function getBucketCandidate(uint8 bucket, uint256 index) external view returns (address);
    function candidateEntryPruned(uint8 bucket, uint256 index) external view returns (bool);
    function isEligibilityExempt(address account) external view returns (bool);
    function minEligibleBucket() external view returns (uint8);
    function eligibilityBps() external view returns (uint256);
}

contract LotteryEngine is Ownable, ReentrancyGuard {
    IRobinhoodToken public token;

    uint256 public constant DRAW_DELAY_BLOCKS = 600;
    uint256 public constant BLOCKHASH_LOOKBACK_LIMIT = 250;
    uint256 public constant MAX_WINNER_ATTEMPTS = 150;
    uint256 public constant MAX_TOTAL_ROUND_ATTEMPTS = 10000;

    uint256 public constant MIN_LOTTERY_BALANCE = 0.5 ether;
    uint256 public constant LOTTERY_COOLDOWN = 1 hours;
    uint256 public constant KEEPER_REWARD_BPS = 200; // 2%
    uint256 public constant MAX_KEEPER_REWARD = 0.02 ether;
    uint256 public constant DEV_FEE_BPS = 1000; // 10%

    address public devWallet;

    enum RoundStatus { NONE, PENDING, FULFILLED, EXPIRED }

    struct Round {
        uint256 roundId;
        address requester;
        uint256 snapshotBlock;
        uint256 randomnessBlock;
        uint256 createdAt;
        uint256 prizePool;
        uint256 eligibleWeightAtSnapshot;
        RoundStatus status;
        uint256[256] snapshotBucketTotals;
        uint256[256] snapshotBucketEntryLengths;
        address winner;
        uint256 winnerAmount;
        uint256 devAmount;
        uint256 keeperReward;
        bytes32 randomnessBlockHash;
        bool prizeReleased;
    }

    uint256 public currentRoundId;
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => uint256) public roundAttemptsCursor;

    uint256 public reservedPrizePool;
    uint256 public totalPendingNativeClaims;
    mapping(address => uint256) public pendingNativeClaims;
    uint256 public lastLotteryTime;

    event LotteryTriggered(uint256 indexed roundId, address indexed requester, uint256 snapshotBlock, uint256 randomnessBlock, uint256 prizePool, uint256 eligibleWeight);
    event LotterySelectionAttempted(uint256 indexed roundId, uint256 attemptsUsed, bool winnerFound);
    event LotteryFulfilled(uint256 indexed roundId, address indexed winner, uint256 winnerAmount, uint256 devAmount, uint256 keeperReward, bytes32 randomnessBlockHash);
    event LotteryExpired(uint256 indexed roundId, string reason);
    event NativeClaimCredited(address indexed account, uint256 amount);
    event NativeClaimPaid(address indexed account, uint256 amount);

    constructor(address _token, address _devWallet) Ownable(msg.sender) {
        token = IRobinhoodToken(_token);
        devWallet = _devWallet;
    }

    receive() external payable {}

    function isLotteryPending() external view returns (bool) {
        return rounds[currentRoundId].status == RoundStatus.PENDING;
    }

    function availableLotteryBalance() public view returns (uint256) {
        uint256 locked = reservedPrizePool + totalPendingNativeClaims;
        if (address(this).balance <= locked) return 0;
        return address(this).balance - locked;
    }

    function _releaseReservedPrize(Round storage r) internal {
        if (!r.prizeReleased) {
            reservedPrizePool -= r.prizePool;
            r.prizeReleased = true;
        }
    }

    function triggerLottery() external nonReentrant {
        require(block.timestamp >= lastLotteryTime + LOTTERY_COOLDOWN, "Lottery cooldown active");

        Round storage currentRound = rounds[currentRoundId];
        require(
            currentRound.status == RoundStatus.NONE || 
            currentRound.status == RoundStatus.FULFILLED || 
            currentRound.status == RoundStatus.EXPIRED, 
            "Lottery in progress"
        );

        uint256 poolBalanceETH = availableLotteryBalance();
        require(token.totalEligibleBalance() > 0, "No eligible holders");
        require(poolBalanceETH >= MIN_LOTTERY_BALANCE, "ETH Pool below minimum");

        uint256 nextRoundId = currentRoundId + 1;

        rounds[nextRoundId].roundId = nextRoundId;
        rounds[nextRoundId].requester = msg.sender;
        rounds[nextRoundId].snapshotBlock = block.number - 1;
        rounds[nextRoundId].randomnessBlock = block.number + DRAW_DELAY_BLOCKS;
        rounds[nextRoundId].createdAt = block.timestamp;
        rounds[nextRoundId].prizePool = poolBalanceETH;
        reservedPrizePool += poolBalanceETH;
        rounds[nextRoundId].eligibleWeightAtSnapshot = token.totalEligibleBalance();
        rounds[nextRoundId].status = RoundStatus.PENDING;

        uint8 minBucket = token.minEligibleBucket();
        for (uint16 i = minBucket; i < 255; i++) {
            uint8 bucket = uint8(i);
            if (token.bucketTotalBalance(bucket) > 0) {
                rounds[nextRoundId].snapshotBucketTotals[bucket] = token.bucketTotalBalance(bucket);
                rounds[nextRoundId].snapshotBucketEntryLengths[bucket] = token.getBucketCandidateLength(bucket);
            }
        }

        currentRoundId = nextRoundId;

        emit LotteryTriggered(nextRoundId, msg.sender, rounds[nextRoundId].snapshotBlock, rounds[nextRoundId].randomnessBlock, poolBalanceETH, token.totalEligibleBalance());
    }

    function getPayoutPercentage(uint256 prizePool) public pure returns (uint256) {
        if (prizePool < 0.5 ether) return 90;
        if (prizePool < 1 ether) return 80;
        if (prizePool < 2 ether) return 60;
        if (prizePool < 5 ether) return 40;
        if (prizePool < 10 ether) return 30;
        if (prizePool < 20 ether) return 20;
        if (prizePool < 50 ether) return 10;
        return 7;
    }

    function msb(uint256 x) internal pure returns (uint8 r) {
        if (x >= 0x100000000000000000000000000000000) { x >>= 128; r += 128; }
        if (x >= 0x10000000000000000) { x >>= 64; r += 64; }
        if (x >= 0x100000000) { x >>= 32; r += 32; }
        if (x >= 0x10000) { x >>= 16; r += 16; }
        if (x >= 0x100) { x >>= 8; r += 8; }
        if (x >= 0x10) { x >>= 4; r += 4; }
        if (x >= 0x4) { x >>= 2; r += 2; }
        if (x >= 0x2) r += 1;
    }

    function _selectBucket(uint256 seed, uint256 totalPool, uint256[256] storage snapshotBucketTotals) private view returns (uint8) {
        uint256 bucketRandom = seed % totalPool;
        uint256 cumulative = 0;

        uint8 minBucket = token.minEligibleBucket();
        for (uint16 i = minBucket; i < 255; i++) {
            uint8 bucket = uint8(i);
            uint256 bTotal = snapshotBucketTotals[bucket];
            if (bTotal > 0) {
                if (bucketRandom < cumulative + bTotal) {
                    return bucket;
                }
                cumulative += bTotal;
            }
        }
        return 0; 
    }

    function _findWinner(Round storage r, uint256 seed, uint256 startAttempt, uint256 endAttempt) internal view returns (address winner, uint256 attemptsUsed) {
        if (r.eligibleWeightAtSnapshot == 0) return (address(0), 0);

        uint256 snapBlock = r.snapshotBlock;
        for (uint256 i = startAttempt; i < endAttempt; i++) {
            attemptsUsed++;
            uint256 currentSeed = uint256(keccak256(abi.encode(seed, i)));

            uint8 winningBucket = _selectBucket(currentSeed, r.eligibleWeightAtSnapshot, r.snapshotBucketTotals);

            uint256 frozenLength = r.snapshotBucketEntryLengths[winningBucket];
            if (winningBucket == 0 || frozenLength == 0) continue;

            uint256 candidateIndex = currentSeed % frozenLength;
            if (token.candidateEntryPruned(winningBucket, candidateIndex)) continue;

            address candidate = token.getBucketCandidate(winningBucket, candidateIndex);

            uint256 snapshotBalance = token.getPastBalance(candidate, snapBlock);
            uint256 threshold = (token.totalSupply() * token.eligibilityBps()) / 10000;
            bool isGhost = (snapshotBalance < threshold || msb(snapshotBalance) != winningBucket);

            bool diamondHands = token.balanceOf(candidate) >= snapshotBalance;
            bool isContract = candidate.code.length > 0;

            if (!isGhost && diamondHands && !token.isEligibilityExempt(candidate) && !isContract) {
                winner = candidate;
                break;
            }
        }
    }

    function finalizeLottery(uint256 roundId) external nonReentrant {
        _finalizeLottery(roundId, MAX_WINNER_ATTEMPTS);
    }

    function finalizeLottery(uint256 roundId, uint256 maxAttempts) external nonReentrant {
        require(maxAttempts > 0, "No attempts");
        require(maxAttempts <= MAX_WINNER_ATTEMPTS, "Too many attempts");
        _finalizeLottery(roundId, maxAttempts);
    }

    function _processWinner(Round storage r, address winner, bytes32 h) internal {
        uint256 keeperReward = (r.prizePool * KEEPER_REWARD_BPS) / 10000;
        if (keeperReward > MAX_KEEPER_REWARD) keeperReward = MAX_KEEPER_REWARD;

        uint256 payoutBase = r.prizePool - keeperReward;
        uint256 totalPayout = (payoutBase * getPayoutPercentage(r.prizePool)) / 100;
        uint256 devAmount = (totalPayout * DEV_FEE_BPS) / 10000;
        uint256 winnerAmount = totalPayout - devAmount;

        r.status = RoundStatus.FULFILLED;
        r.winner = winner;
        r.winnerAmount = winnerAmount;
        r.devAmount = devAmount;
        r.keeperReward = keeperReward;

        _releaseReservedPrize(r);
        totalPendingNativeClaims += winnerAmount + devAmount + keeperReward;

        pendingNativeClaims[winner] += winnerAmount;
        pendingNativeClaims[devWallet] += devAmount;
        pendingNativeClaims[msg.sender] += keeperReward;

        emit NativeClaimCredited(winner, winnerAmount);
        emit NativeClaimCredited(devWallet, devAmount);
        emit NativeClaimCredited(msg.sender, keeperReward);

        emit LotteryFulfilled(r.roundId, winner, winnerAmount, devAmount, keeperReward, h);
    }

    function _finalizeLottery(uint256 roundId, uint256 maxAttempts) internal {
        Round storage r = rounds[roundId];
        require(r.status == RoundStatus.PENDING, "Not pending");
        require(block.number > r.randomnessBlock, "Too early");

        bytes32 h = r.randomnessBlockHash;
        if (h == bytes32(0)) {
            if (block.number > r.randomnessBlock + BLOCKHASH_LOOKBACK_LIMIT) {
                r.status = RoundStatus.EXPIRED;
                _releaseReservedPrize(r);
                emit LotteryExpired(roundId, "250-block lookback missed");
                return;
            }
            h = blockhash(r.randomnessBlock);
            require(h != bytes32(0), "Randomness blockhash unavailable");
            r.randomnessBlockHash = h;
        }

        uint256 seed = uint256(keccak256(abi.encodePacked(
            h,
            r.roundId,
            r.snapshotBlock,
            r.prizePool,
            address(this),
            block.chainid
        )));

        uint256 startAttempt = roundAttemptsCursor[roundId];
        uint256 remaining = MAX_TOTAL_ROUND_ATTEMPTS - startAttempt;
        if (maxAttempts > remaining) maxAttempts = remaining;

        uint256 endAttempt = startAttempt + maxAttempts;

        (address winner, uint256 attemptsUsed) = _findWinner(r, seed, startAttempt, endAttempt);

        roundAttemptsCursor[roundId] = startAttempt + attemptsUsed;
        emit LotterySelectionAttempted(roundId, attemptsUsed, winner != address(0));

        lastLotteryTime = block.timestamp;

        if (winner != address(0)) {
            _processWinner(r, winner, h);
        } else if (startAttempt + attemptsUsed >= MAX_TOTAL_ROUND_ATTEMPTS) {
            r.status = RoundStatus.EXPIRED;
            _releaseReservedPrize(r);
            emit LotteryExpired(roundId, "No valid winner after max total attempts");
        }
    }

    function expireRound(uint256 roundId) external {
        Round storage r = rounds[roundId];
        require(r.status == RoundStatus.PENDING, "Not pending");
        require(r.randomnessBlockHash == bytes32(0), "Randomness captured; continue finalize");
        require(block.number > r.randomnessBlock + BLOCKHASH_LOOKBACK_LIMIT, "Lookback window still active");

        r.status = RoundStatus.EXPIRED;
        _releaseReservedPrize(r);
        emit LotteryExpired(roundId, "Expired manually");
    }

    function claimNative() external nonReentrant {
        uint256 amount = pendingNativeClaims[msg.sender];
        require(amount > 0, "No pending native claims");

        pendingNativeClaims[msg.sender] = 0;
        totalPendingNativeClaims -= amount;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "ETH transfer failed");

        emit NativeClaimPaid(msg.sender, amount);
    }
}

