// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface ILotteryEngine {
    function isLotteryPending() external view returns (bool);
}

contract RobinhoodToken is ERC20, Ownable {
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;

    function eligibilityBps() external pure returns (uint256) {
        return 10; // 0.1%
    }

    uint256 public tradingActivatedAt;

    struct Checkpoint {
        uint32 fromBlock;
        uint224 balance;
    }
    mapping(address => Checkpoint[]) public checkpoints;

    mapping(address => bool) public isTradingExempt;
    mapping(address => bool) public isMaxWalletExempt;
    mapping(address => bool) public isEligibilityExempt;

    address public lotteryEngine;

    // Eligibility and Buckets
    uint256 public totalEligibleBalance; 
    uint256[256] public bucketTotalBalance; 
    mapping(uint8 => address[]) public bucketHolders; 
    mapping(address => uint8) public userBucket; 
    mapping(address => uint256) public holderIndex; 

    mapping(uint8 => address[]) public bucketCandidateEntries;
    mapping(address => mapping(uint8 => uint256)) public activeCandidateEntryIndexPlusOne;
    mapping(uint8 => mapping(uint256 => bool)) public candidateEntryPruned;

    event HolderBecameEligible(address indexed holder, uint256 balance);
    event HolderRemovedFromEligibility(address indexed holder, uint256 balance);

    constructor() ERC20("Robinhood", "RHT") Ownable(msg.sender) {
        _mint(msg.sender, TOTAL_SUPPLY);
        isTradingExempt[msg.sender] = true;
        isMaxWalletExempt[msg.sender] = true;
        isEligibilityExempt[msg.sender] = true;

        isTradingExempt[address(this)] = true;
        isMaxWalletExempt[address(this)] = true;
        isEligibilityExempt[address(this)] = true;
    }

    function setExemptions(address account, bool trading, bool maxWallet, bool eligibility) external onlyOwner {
        isTradingExempt[account] = trading;
        isMaxWalletExempt[account] = maxWallet;
        isEligibilityExempt[account] = eligibility;
    }

    function setLotteryEngine(address _engine) external onlyOwner {
        require(lotteryEngine == address(0), "Engine already set");
        require(_engine != address(0), "Invalid engine");
        lotteryEngine = _engine;
    }

    function activateTrading() external onlyOwner {
        require(tradingActivatedAt == 0, "Already active");
        tradingActivatedAt = block.timestamp;
    }

    function getMaxWallet() public view returns (uint256) {
        if (tradingActivatedAt == 0) return totalSupply();
        uint256 elapsed = block.timestamp - tradingActivatedAt;
        if (elapsed >= 30 minutes) return (totalSupply() * 3) / 100;

        uint256 startMax = (totalSupply() * 1) / 100;
        uint256 maxIncrease = (totalSupply() * 2) / 100;

        return startMax + ((maxIncrease * elapsed) / (30 minutes));
    }

    function msb(uint256 x) internal pure returns (uint8 r) {
        if (x >= 0x100000000000000000000000000000000) { x >>= 128; r += 128; }
        if (x >= 0x10000000000000000) { x >>= 64; r += 64; }
        if (x >= 0x100000000) { x >>= 32; r += 32; }
        if (x >= 0x10000) { x >>= 16; r += 16; }
        if (x >= 0x100) { x >>= 8; r += 8; }
        if (x >= 0x10) { x >>= 4; r += 4; }
        if (x >= 0x4) { x >>= 2; r += 2; }
        if (x >= 0x2) r += 1;
    }

    function minEligibleBucket() public view returns (uint8) {
        uint256 minBal = (totalSupply() * 10) / 10000;
        return msb(minBal);
    }

    function pruneCandidateEntry(uint8 bucket, uint256 index) external {
        if (lotteryEngine != address(0)) {
            require(!ILotteryEngine(lotteryEngine).isLotteryPending(), "Lottery pending");
        }

        require(index < bucketCandidateEntries[bucket].length, "Out of bounds");
        address candidate = bucketCandidateEntries[bucket][index];
        uint256 bal = getPastBalance(candidate, block.number - 1);
        uint256 threshold = (totalSupply() * 10) / 10000;
        if (bal < threshold || msb(bal) != bucket) {
            candidateEntryPruned[bucket][index] = true;
            if (activeCandidateEntryIndexPlusOne[candidate][bucket] == index + 1) {
                activeCandidateEntryIndexPlusOne[candidate][bucket] = 0;
            }
        }
    }

    function _updateEligibility(address account, uint256 oldBal, uint256 newBal) internal {
        if (isEligibilityExempt[account] || account.code.length > 0) return;

        uint256 threshold = (totalSupply() * 10) / 10000;
        uint8 oldBucket = oldBal >= threshold ? msb(oldBal) : 0;
        uint8 newBucket = newBal >= threshold ? msb(newBal) : 0;

        if (oldBucket == newBucket) {
            if (oldBucket != 0) {
                bucketTotalBalance[oldBucket] = bucketTotalBalance[oldBucket] - oldBal + newBal;
                totalEligibleBalance = totalEligibleBalance - oldBal + newBal;
            }
        } else {
            if (oldBucket != 0) {
                bucketTotalBalance[oldBucket] -= oldBal;
                totalEligibleBalance -= oldBal;

                uint256 index = holderIndex[account];
                uint256 lastIndex = bucketHolders[oldBucket].length - 1;
                address lastAccount = bucketHolders[oldBucket][lastIndex];

                bucketHolders[oldBucket][index] = lastAccount;
                holderIndex[lastAccount] = index;
                bucketHolders[oldBucket].pop();
                holderIndex[account] = 0;

                if (newBucket == 0) emit HolderRemovedFromEligibility(account, newBal);
            }
            if (newBucket != 0) {
                bucketTotalBalance[newBucket] += newBal;
                totalEligibleBalance += newBal;

                bucketHolders[newBucket].push(account);
                holderIndex[account] = bucketHolders[newBucket].length - 1;

                if (activeCandidateEntryIndexPlusOne[account][newBucket] == 0) {
                    bucketCandidateEntries[newBucket].push(account);
                    activeCandidateEntryIndexPlusOne[account][newBucket] = bucketCandidateEntries[newBucket].length;
                }

                if (oldBucket == 0) emit HolderBecameEligible(account, newBal);
            }
            userBucket[account] = newBucket;
        }
    }

    function _update(address from, address to, uint256 amount) internal override {
        if (from == address(0) || to == address(0) || amount == 0) {
            super._update(from, to, amount);
            _writeCheckpoint(from, balanceOf(from));
            _writeCheckpoint(to, balanceOf(to));
            return;
        }

        if (tradingActivatedAt == 0) {
            require(isTradingExempt[from] && isTradingExempt[to], "Trading not active");
        }

        uint256 transferAmount = amount;

        uint256 fromOldBal = balanceOf(from);
        uint256 toOldBal = balanceOf(to);

        if (!isMaxWalletExempt[to]) {
            require(toOldBal + transferAmount <= getMaxWallet(), "Exceeds max wallet limit");
        }

        super._update(from, to, amount);

        uint256 fromNewBal = fromOldBal - amount;
        uint256 toNewBal = toOldBal + amount;

        _writeCheckpoint(from, fromNewBal);
        _writeCheckpoint(to, toNewBal);

        _updateEligibility(from, fromOldBal, fromNewBal);
        _updateEligibility(to, toOldBal, toNewBal);
    }

    function getPastBalance(address account, uint256 blockNumber) public view returns (uint256) {
        require(blockNumber < block.number, "Balance checkpoint: block not yet mined");
        Checkpoint[] storage ckpts = checkpoints[account];
        uint256 high = ckpts.length;
        uint256 low = 0;
        while (low < high) {
            uint256 mid = low + (high - low) / 2;
            if (ckpts[mid].fromBlock > blockNumber) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return high == 0 ? 0 : ckpts[high - 1].balance;
    }

    function _writeCheckpoint(address account, uint256 newBalance) internal {
        Checkpoint[] storage ckpts = checkpoints[account];
        uint256 length = ckpts.length;
        if (length > 0 && ckpts[length - 1].fromBlock == block.number) {
            ckpts[length - 1].balance = uint224(newBalance);
        } else {
            ckpts.push(Checkpoint({fromBlock: uint32(block.number), balance: uint224(newBalance)}));
        }
    }

    // Functions for Lottery Engine to read
    function getBucketCandidateLength(uint8 bucket) public view returns (uint256) {
        return bucketCandidateEntries[bucket].length;
    }

    function getBucketCandidate(uint8 bucket, uint256 index) public view returns (address) {
        return bucketCandidateEntries[bucket][index];
    }
}

